<section class="card"><div class="card-header"><h2>Ordini acquisiti</h2></div><div class="table-wrap"><table><thead><tr><th>Data</th><th>Canale</th><th>ID esterno</th><th>Cliente</th><th>Totale</th><th>Stato</th><th>Importazione</th><th></th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><?= View::date($o['order_date']) ?></td><td><?= View::e($o['channel_name']??$o['platform']) ?></td><td class="primary-cell"><?= View::e($o['external_order_id']) ?></td><td><?= View::e($o['customer_email']??'—') ?></td><td><?= View::money($o['total']) ?></td><td><?= View::e(View::label($o['status'])) ?></td><td><span class="badge status-<?= strtolower($o['import_status']) ?>"><?= View::e($o['import_status']) ?></span></td><td><?php if(!$o['luna_document_id']):?><form method="post" action="/operations/ecommerce/orders/<?= (int)$o['id'] ?>/convert"><input type="hidden" name="_token" value="<?= $token ?>"><button class="button primary">Crea ordine Luna</button></form><?php else:?><a class="button" href="/documents/orders/<?= (int)$o['luna_document_id'] ?>">Apri ordine</a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section>
